"""
Generates docs/data_dictionary.md from the configuration files,
so the documentation can never drift from what is applied to HubSpot.

Usage:  python src/generate_data_dictionary.py
"""

from config_loader import ROOT, load_all

TYPE_LABELS = {
    "enumeration": "Dropdown", "number": "Number", "currency_number": "Currency (BRL)",
    "bool": "Yes/No", "date": "Date", "datetime": "Date and time", "string": "Text",
}


def build(config: dict) -> str:
    lines = [
        "# Data dictionary",
        "",
        "_Generated by `src/generate_data_dictionary.py` from `config/`. Do not edit by hand._",
        "",
    ]
    # ---- propriedades
    for obj, props in config["properties"].items():
        lines += [f"## {obj.capitalize()}", "",
                  "| Label | Internal name | Type | Owner | Req. | Description | Options |",
                  "|---|---|---|---|---|---|---|"]
        for p in props:
            options = "<br>".join(f"`{v}` {label}" for v, label in p.get("options", []))
            lines.append(f"| {p['label']} | `{p['internal_name']}` | {TYPE_LABELS[p['type']]} "
                         f"| {p['owner']} | {p['requirement']} | {p['description']} | {options} |")
        lines.append("")

    # ---- pipelines
    lines += ["## Pipelines", ""]
    for obj, pipes in config["pipelines"].items():
        for pipe in pipes:
            lines += [f"### {pipe['label']} ({obj})", "", pipe["description"], ""]
            if obj == "deals":
                lines += ["| # | Stage | Probability | Entry criteria | Exit criteria |",
                          "|---|---|---|---|---|"]
                for i, s in enumerate(pipe["stages"], 1):
                    lines.append(f"| {i} | {s['label']} | {s['probability']:.0%} | {s['entry']} "
                                 f"| {s.get('exit', '—')} |")
            else:
                lines += ["| # | Stage | State | Entry criteria | Exit criteria |",
                          "|---|---|---|---|---|"]
                for i, s in enumerate(pipe["stages"], 1):
                    lines.append(f"| {i} | {s['label']} | {s['state']} | {s['entry']} "
                                 f"| {s.get('exit', '—')} |")
            lines.append("")

    # ---- segmentos
    lines += ["## Segments", "", "| Segment | Object | Purpose | Filter |", "|---|---|---|---|"]
    for s in config["segments"]:
        lines.append(f"| {s['name']} | {s['object']} | {s['purpose']} | `{s['filter']}` |")
    lines.append("")

    # ---- permissões
    teams = config["teams"]
    cols = teams["permission_columns"]
    lines += ["## Permission matrix", "",
              "| Team | " + " | ".join(c.capitalize() for c in cols) + " |",
              "|---|" + "---|" * len(cols)]
    for team, levels in teams["permissions"].items():
        lines.append(f"| {team} | " + " | ".join(l.replace("_", " ") for l in levels) + " |")
    lines += ["", *[f"- {r}" for r in teams["rules"]], ""]
    return "\n".join(lines)


def main() -> None:
    out = ROOT / "docs" / "data_dictionary.md"
    out.write_text(build(load_all()), encoding="utf-8")
    print(f"Written: {out.relative_to(ROOT)}")


if __name__ == "__main__":
    main()
